const cfg = $('Set config: JD, resume, keys & rules').first().json;
const jd = cfg.jd || '';
const resumeText = cfg.resume || '';
const target = cfg.target || '';
const schema = { type: 'object', additionalProperties: false, required: ['name','title','contact','summary','experience','skills','education','match_score','key_changes','keywords_matched','gaps','suggestions'], properties: {
  name: { type: 'string' }, title: { type: 'string' }, contact: { type: 'string' }, summary: { type: 'string' },
  experience: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['role','company','dates','bullets'], properties: {
    role: { type: 'string' }, company: { type: 'string' }, dates: { type: 'string' }, bullets: { type: 'array', items: { type: 'string' } } } } },
  skills: { type: 'array', items: { type: 'string' } }, education: { type: 'array', items: { type: 'string' } },
  match_score: { type: 'integer' },
  key_changes: { type: 'array', items: { type: 'string' } }, keywords_matched: { type: 'array', items: { type: 'string' } },
  gaps: { type: 'array', items: { type: 'string' } }, suggestions: { type: 'array', items: { type: 'string' } } } };
const system = 'You are an expert resume writer and ATS specialist. Rewrite the candidate resume to fit the target job. HARD RULES: ' + cfg.rules;
const user = 'Return the structured fields. match_score = 0-100 honest fit of the candidate to this job BEFORE tailoring. key_changes = what you emphasised/reordered and why. keywords_matched = JD terms now genuinely reflected. gaps = JD requirements the candidate does not clearly meet (be honest). suggestions = concrete things the candidate could do or add (courses, projects, framing) to close the gaps.'
  + '\n\nTARGET ROLE/COMPANY: ' + (target || '(not specified)')
  + '\n\n=== TARGET JOB DESCRIPTION ===\n' + jd
  + '\n\n=== CANDIDATE RESUME (Markdown, source of truth - add nothing not supported here) ===\n' + resumeText;
return [{ json: { body: {
  model: cfg.model || 'claude-haiku-4-5', max_tokens: 2500, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

const cfg = $('Set config: JD, resume, keys & rules').first().json;
const accent = cfg.accent || '#1a56db';
const blocks = $json.content || [];
let out = {};
try { out = JSON.parse((blocks.find((b) => b.type === 'text') || {}).text || '{}'); } catch (e) {}
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const exp = (out.experience || []).map((e) =>
  '<div class="job"><div class="jobhead"><span class="role">' + esc(e.role) + '</span><span class="dates">' + esc(e.dates) + '</span></div>' +
  '<div class="company">' + esc(e.company) + '</div><ul>' + (e.bullets || []).map((b) => '<li>' + esc(b) + '</li>').join('') + '</ul></div>').join('');
const html =
  '<!doctype html><html><head><meta charset="utf-8"><style>' +
  '*{box-sizing:border-box} body{font-family:Georgia,\'Times New Roman\',serif;color:#222;margin:0;padding:40px 48px;font-size:11pt;line-height:1.4}' +
  'h1{font-size:22pt;margin:0;color:' + accent + '} .title{font-size:12pt;color:#555;margin:2px 0 6px} .contact{font-size:9.5pt;color:#666;margin-bottom:14px}' +
  'h2{font-size:11pt;text-transform:uppercase;letter-spacing:.06em;color:' + accent + ';border-bottom:1.5px solid ' + accent + ';padding-bottom:2px;margin:16px 0 8px}' +
  '.job{margin-bottom:10px} .jobhead{display:flex;justify-content:space-between} .role{font-weight:bold} .dates{color:#777;font-size:9.5pt} .company{font-style:italic;color:#444;margin-bottom:3px}' +
  'ul{margin:3px 0 0 18px;padding:0} li{margin:2px 0} .skills{font-size:10pt}</style></head><body>' +
  '<h1>' + esc(out.name) + '</h1><div class="title">' + esc(out.title) + '</div><div class="contact">' + esc(out.contact) + '</div>' +
  (out.summary ? '<h2>Summary</h2><div>' + esc(out.summary) + '</div>' : '') +
  '<h2>Experience</h2>' + exp +
  (out.skills && out.skills.length ? '<h2>Skills</h2><div class="skills">' + out.skills.map(esc).join(' &nbsp;·&nbsp; ') + '</div>' : '') +
  (out.education && out.education.length ? '<h2>Education</h2><ul>' + out.education.map((e) => '<li>' + esc(e) + '</li>').join('') + '</ul>' : '') +
  '</body></html>';
const listp = (a) => Array.isArray(a) && a.length ? '<ul>' + a.map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '<p>none</p>';
const score = typeof out.match_score === 'number' ? out.match_score : null;
const detailsHtml =
  (score !== null ? '<p style="font-size:16px"><strong>Match score:</strong> <span style="color:' + (score >= 75 ? '#0a0' : score >= 50 ? '#c80' : '#c00') + '">' + score + '/100</span> (before tailoring)</p>' : '') +
  '<h3>What changed</h3>' + listp(out.key_changes) +
  '<h3>ATS keywords covered</h3>' + listp(out.keywords_matched) +
  '<h3 style="color:#a00">Gaps vs the JD</h3>' + listp(out.gaps) +
  '<h3>Suggestions to close the gaps</h3>' + listp(out.suggestions);
const authHeader = 'Basic ' + Buffer.from('api:' + (cfg.pdfApiKey || '')).toString('base64');
return [{ json: { html, detailsHtml, authHeader, deliverTo: cfg.email } }];
